INSERT OR IGNORE INTO "chunks" ("id", "chunk_id", "clause_id", "text", "part", "section", "clause", "title", "page", "tables_json", "requirement_ids_json", "source_hash") VALUES ('chunk-3141','GHBC-CHUNK-003141','GHBC-C-003141','A minimum of 85 percent of insulation shall comply with the requirements of Table 13.6.6(1) or Table 13.8.6(2). The test methodology used to determine compliance shall be from CDPH/EHLB/Standard Method V.1.1. The emissions testing shall be performed by a laboratory that has the CDPH/EHLB/Standard Method V.1.1 test methodology in the scope of its ISO 17025 Accreditation.',13,'13.6.6',NULL,NULL,582,'["TABLE 13.6.6(1)"]','["GHBC-REQ-011096","GHBC-REQ-011097","GHBC-REQ-011098"]','24a7298222e597a3d7d51c4f3b1f703ebd9a7aaf668bb9969844e81d4c6bc4a6'),
