INSERT OR IGNORE INTO "chunks" ("id", "chunk_id", "clause_id", "text", "part", "section", "clause", "title", "page", "tables_json", "requirement_ids_json", "source_hash") VALUES ('chunk-4521','GHBC-CHUNK-004521','GHBC-C-004521','25.4.3.5
